const ALL_TOPICS=[...TOPICS,...TOPICS2,...TOPICS3,...TOPICS4,...TOPICS5,...TOPICS6];
const DB=process.env.DB_NAME;
async function run(){
  await mongoose.connect(DB);
  console.log("Connected to MongoDB");
  let path=await PracticePath.findOne({slug:SLUG});
  if(!path){
    path=await PracticePath.create({title:"Full Stack Development",slug:SLUG,description:"Complete practice path covering HTML, CSS, JS, React, Git, Node.js, MongoDB, Deployment, Auth, REST APIs, Advanced React, DevOps and Capstone.",level:"Intermediate",themeColor:"#6366f1",gradientFrom:"#6366f1",gradientTo:"#8b5cf6",estimatedDuration:"60 hours",order:2,isPublished:true});
    console.log("Created path:",path.title);
  } else {
    console.log("Using existing path:",path.title);
  }
  let tc=0,sc=0,qc=0;
  for(let ti=0;ti<ALL_TOPICS.length;ti++){
    const td=ALL_TOPICS[ti];
    let topic=await PracticeTopic.findOne({practicePath:path._id,slug:td.slug});
    if(!topic){
      topic=await PracticeTopic.create({practicePath:path._id,title:td.title,slug:td.slug,description:td.desc,order:ti+1,isPublished:true});
      tc++;
    }
    console.log("Topic "+(ti+1)+":",topic.title);
    for(let si=0;si<td.subs.length;si++){
      const sd=td.subs[si];
      const stSlug=sl(sd.title)+"-st"+si;
      let sub=await PracticeSubtopic.findOne({topic:topic._id,slug:stSlug});
      if(!sub){
        sub=await PracticeSubtopic.create({topic:topic._id,practicePath:path._id,title:sd.title,slug:stSlug,description:sd.desc||"",order:si+1,isPublished:true});
        sc++;
      }
      const base={practicePath:path._id,topic:topic._id,type:"mcq",isPublished:true,tags:["full-stack","seed"]};
      await makeQs(base,sub,sd.qs);
      qc+=sd.qs.length;
      console.log("  Subtopic:",sub.title,"-",sd.qs.length,"Qs");
    }
  }
  console.log("\n Done! Topics:"+tc+" Subtopics:"+sc+" Questions:"+qc);
  await mongoose.disconnect();
}
run().catch(e=>{console.error("Seed failed:",e.message);process.exit(1);});
